USE m2;
DROP TABLE IF EXISTS orders; DROP TABLE IF EXISTS customers; DROP TABLE IF EXISTS regions;
CREATE TABLE regions (id INT PRIMARY KEY, name VARCHAR(20) NOT NULL) ENGINE=InnoDB;
CREATE TABLE customers (id INT PRIMARY KEY, region_id INT NOT NULL, pad CHAR(60) NOT NULL DEFAULT '') ENGINE=InnoDB;
CREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, status VARCHAR(10) NOT NULL, pad CHAR(60) NOT NULL DEFAULT '') ENGINE=InnoDB;
-- 50 regions; region 1 is 'EU'
INSERT INTO regions SELECT n, IF(n=1,'EU',CONCAT('R',n)) FROM (SELECT a.n+b.n*10+1 AS n FROM (SELECT 0 n UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a, (SELECT 0 n UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4) b) t;
-- numbers helper
DROP TABLE IF EXISTS nums; CREATE TABLE nums (n INT PRIMARY KEY) ENGINE=InnoDB;
INSERT INTO nums SELECT a.d + b.d*10 + c.d*100 + d.d*1000 + e.d*10000 + f.d*100000 + 1
FROM (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a,
     (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) b,
     (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) c,
     (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) d,
     (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) e,
     (SELECT 0 d UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) f;
-- 100,000 customers spread over 50 regions; 1,000,000 orders (10 per customer), 2% 'open'
INSERT INTO customers (id, region_id) SELECT n, (n MOD 50)+1 FROM nums WHERE n<=100000;
INSERT INTO orders (id, customer_id, status) SELECT n, ((n-1) MOD 100000)+1, IF(n MOD 50 = 0,'open','closed') FROM nums;
SELECT (SELECT COUNT(*) FROM regions) regions,(SELECT COUNT(*) FROM customers) customers,(SELECT COUNT(*) FROM orders) orders,
       (SELECT COUNT(*) FROM orders WHERE status='open') open_orders;
